import { useEffect, useState } from "react";
import type { ReactNode } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface AnnouncementAction {
  label: string;
  onClick?: () => void;
}

export interface Announcement {
  id: string;
  message: ReactNode;
  action?: AnnouncementAction;
}

export interface AnnouncementBarProps {
  messages: Announcement[];
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Milliseconds each message stays before the next one. */
  interval?: number;
  autoPlay?: boolean;
  /** Extend the inner, named parts of the bar: root, message, action, dots or dismiss. The React Native counterpart of `classNames`. */
  styles?: {
    root?: StyleProp<ViewStyle>;
    message?: StyleProp<TextStyle>;
    action?: StyleProp<TextStyle>;
    dismiss?: StyleProp<ViewStyle>;
  };
}

export function AnnouncementBar({ messages, open, defaultOpen = true, onOpenChange, interval = 6000, autoPlay = true, styles: parts }: AnnouncementBarProps) {
  const tokens = useTokens();
  const [internal, setInternal] = useState(defaultOpen);
  const [index, setIndex] = useState(0);
  const visible = open ?? internal;

  useEffect(() => {
    if (!autoPlay || messages.length < 2) return;
    const timer = setInterval(() => setIndex((current) => (current + 1) % messages.length), interval);
    return () => clearInterval(timer);
  }, [autoPlay, interval, messages.length]);

  if (!visible || messages.length === 0) return null;
  const current = messages[index % messages.length];

  return (
    <View accessibilityRole="alert" style={[local.root, { backgroundColor: tokens.foreground }, parts?.root]}>
      <View style={local.copy}>
        {typeof current.message === "string" ? <Text style={[{ color: tokens.background, fontSize: metrics.text.sm }, parts?.message]}>{current.message}</Text> : current.message}
        {current.action ? (
          <Pressable accessibilityRole="link" onPress={current.action.onClick} hitSlop={6}>
            <Text style={[{ color: tokens.background, fontSize: metrics.text.sm, fontWeight: "600", textDecorationLine: "underline" }, parts?.action]}>{current.action.label}</Text>
          </Pressable>
        ) : null}
      </View>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel="Dismiss announcement"
        hitSlop={8}
        onPress={() => {
          if (open === undefined) setInternal(false);
          onOpenChange?.(false);
        }}
        style={parts?.dismiss}
      >
        <Text style={{ color: tokens.background, fontSize: 18, lineHeight: 20 }}>×</Text>
      </Pressable>
    </View>
  );
}

const local = StyleSheet.create({
  root: { flexDirection: "row", alignItems: "center", justifyContent: "space-between", gap: metrics.space[3], paddingVertical: metrics.space[3], paddingHorizontal: metrics.space[4] },
  copy: { flex: 1, flexDirection: "row", flexWrap: "wrap", alignItems: "center", gap: metrics.space[2] },
});

export default AnnouncementBar;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
